# 整目录替换安装
function Get-TreeFiles { param([string]$Root); if(Test-Path $Root){Get-ChildItem $Root -Recurse -File} }
function Install-DownloadedVersion { param([string]$Source,[string]$GameDir,[switch]$DryRun)
 if(!(Test-Path $Source)){throw '下载目录不存在'};if($DryRun){return @(Get-TreeFiles $Source)}
 $files=@(Get-TreeFiles $Source);$total=[Int64](($files|Measure-Object Length -Sum).Sum);$drive=[IO.Path]::GetPathRoot($GameDir);$free=[IO.DriveInfo]::new($drive).AvailableFreeSpace;$moved=$false;$parent=Split-Path $GameDir -Parent;$backup=Join-Path $parent ((Split-Path $GameDir -Leaf)+'.backup_'+(Get-Date -Format yyyyMMdd_HHmmss))
 if((Test-Path $GameDir) -and $free -lt $total){Write-Host ('磁盘剩余 '+(Format-Bytes -Bytes $free)+'，安装至少需要 '+(Format-Bytes -Bytes $total)+'。') -ForegroundColor Yellow;$answer=(Read-Host '空间不足，是否删除现有游戏目录后继续？(Y/N，默认 N)').Trim().ToUpperInvariant();if($answer -ne 'Y'){throw '空间不足，用户取消安装'};Remove-Item $GameDir -Recurse -Force}
 try {if((Test-Path $GameDir)){Move-Item $GameDir $backup;$moved=$true};New-Item $GameDir -ItemType Directory -Force|Out-Null;$done=0L;$i=0;$start=Get-Date;foreach($f in $files){$rel=$f.FullName.Substring($Source.Length).TrimStart('\');$dest=Join-Path $GameDir $rel;$d=Split-Path $dest -Parent;if(!(Test-Path $d)){New-Item $d -ItemType Directory -Force|Out-Null};Copy-Item $f.FullName $dest -Force;$done+=$f.Length;$i++;$pct=if($total){$done/$total*100}else{100};$rate=[Int64]($done/[Math]::Max(1,((Get-Date)-$start).TotalSeconds));Write-Progress -Activity '替换游戏目录' -Status ('{0:N1}% {1}/{2} 文件 {3}/{4} {5}/s' -f $pct,$i,$files.Count,(Format-Bytes -Bytes $done),(Format-Bytes -Bytes $total),(Format-Bytes -Bytes $rate)) -PercentComplete $pct};Write-Progress -Activity '替换游戏目录' -Completed;if($moved){Remove-Item $backup -Recurse -Force};Write-Host '安装完成，下载缓存默认保留。' -ForegroundColor Green;$remove=(Read-Host '是否删除下载缓存？(Y/N，默认 N)').Trim().ToUpperInvariant();if($remove -eq 'Y'){Remove-Item $Source -Recurse -Force;Write-Host '已删除下载缓存。' -ForegroundColor Green}else{Write-Host ('已保留下载缓存: '+$Source) -ForegroundColor Cyan};[pscustomobject]@{Success=$true;Destination=$GameDir;Files=$files.Count}}catch{if(Test-Path $GameDir){Remove-Item $GameDir -Recurse -Force};if($moved -and (Test-Path $backup)){Move-Item $backup $GameDir -Force};throw}
}
